   348	// 自动重连机制回调函数
   349	void LBot::reconnect_timer_callback()
   350	{
   351	    if (shutting_down_) return;
   352	    if (conn_state_ != GlobalConnState::DISCONNECTED) return;
   353	
   354	    std::lock_guard<std::mutex> lock(reconnect_thread_mutex_);
   355	
   356	    if (reconnect_thread_running_)
   357	        return;  // 线程正在运行，不重复启动
   358	
   359	    reconnect_thread_running_ = true;
   360	
   361	    reconnect_thread_ = std::thread([this]() {
   362	        if (shutting_down_) {
   363	            reconnect_thread_running_ = false;
   364	            return;
   365	        }
   366	
   367	        RCLCPP_INFO(this->get_logger(), "Trying to reconnect to LBot...");
   368	
   369	        bool success = connect_robot();
   370	
   371	        {
   372	            std::lock_guard<std::mutex> lock(conn_mutex_);
   373	            if (success) {
   374	                conn_state_ = GlobalConnState::CONNECTED;
   375	                heartbeat_fail_count_ = 0;
   376	
   377	                if (!shutting_down_)
   378	                    RCLCPP_INFO(this->get_logger(), "Arm reconnected successfully");
   379	            } else {
   380	                conn_state_ = GlobalConnState::DISCONNECTED;
   381	
   382	                if (!shutting_down_)
   383	                    RCLCPP_WARN(this->get_logger(), "Reconnection failed. Will retry...");
   384	            }
   385	        }
   386	
   387	        reconnect_thread_running_ = false;
   388	    });
   389	}
