L289: void ImageView::updateTopicList()
L290: {
L291:   QSet<QString> message_types;
L292:   message_types.insert("sensor_msgs/Image");
L293:   message_types.insert("sensor_msgs/msg/Image");
L294:   QSet<QString> message_sub_types;
L295:   message_sub_types.insert("sensor_msgs/CompressedImage");
L296:   message_sub_types.insert("sensor_msgs/msg/CompressedImage");
L297:   // get declared transports
L298:   QList<QString> transports;
L299:   image_transport::ImageTransport it{*node_};
L300:   std::vector<std::string> declared = it.getDeclaredTransports();
L301:   for (std::vector<std::string>::const_iterator it = declared.begin(); it != declared.end(); it++) {
L302:     // qDebug("ImageView::updateTopicList() declared transport '%s'", it->c_str());
L303:     QString transport = it->c_str();
L304:     // strip prefix from transport name
L305:     QString prefix = "image_transport/";
L306:     if (transport.startsWith(prefix)) {
L307:       transport = transport.mid(prefix.length());
L308:     }
L309:     transports.append(transport);
L310:   }
L311: 
L312:   QString selected = ui_.topics_combo_box->currentText();
L313:   // fill combo box
L314:   QList<QString> topics = getTopics(message_types, message_sub_types, transports).values();
L315:   topics.append("");
L316:   std::sort(topics.begin(), topics.end());
L317:   ui_.topics_combo_box->clear();
L318:   for (QList<QString>::const_iterator it = topics.begin(); it != topics.end(); it++) {
L319:     QString label(*it);
L320:     label.replace(" ", "/");
L321:     ui_.topics_combo_box->addItem(label, QVariant(*it));
L322:   }
L323: 
L324:   // restore previous selection
L325:   selectTopic(selected);
L326: }
L327: QSet<QString> ImageView::getTopics(
L328:   const QSet<QString> & message_types,
L329:   const QSet<QString> & message_sub_types, const QList<QString> & transports)
L330: {
L331:   std::map<std::string, std::vector<std::string>> topic_info = node_->get_topic_names_and_types();
L332: 
L333:   QSet<QString> all_topics;
L334:   for (std::map<std::string, std::vector<std::string>>::iterator it = topic_info.begin();
L335:     it != topic_info.end(); ++it)
L336:   {
L337:     all_topics.insert(it->first.c_str());
L338:   }
L339:   QSet<QString> topics;
L340:   for (std::map<std::string, std::vector<std::string>>::iterator it = topic_info.begin();
L341:     it != topic_info.end(); ++it)
L342:   {
L343:     for (std::vector<std::string>::const_iterator msg_type_it = it->second.begin();
L344:       msg_type_it != it->second.end(); ++msg_type_it)
L345:     {
L346:       if (message_types.contains(msg_type_it->c_str())) {
L347:         QString topic = it->first.c_str();
L348:         // add raw topic
L349:         topics.insert(topic);
L350:         // qDebug("ImageView::getTopics() raw topic '%s'", topic.toStdString().c_str());
L351:         // add transport specific sub-topics
L352:         for (QList<QString>::const_iterator jt = transports.begin(); jt != transports.end(); jt++) {
L353:           if (all_topics.contains(topic + "/" + *jt)) {
L354:             QString sub = topic + " " + *jt;
L355:             topics.insert(sub);
L356:             // qDebug("ImageView::getTopics() transport specific sub-topic '%s'",
L357:             //   sub.toStdString().c_str());
L358:           }
L359:         }
L360:       }
L361:       if (message_sub_types.contains(msg_type_it->c_str())) {
L362:         QString topic = it->first.c_str();
L363:         int index = topic.lastIndexOf("/");
L364:         if (index != -1) {
L365:           topic.replace(index, 1, " ");
L366:           topics.insert(topic);
L367:           // qDebug("ImageView::getTopics() transport specific sub-topic '%s'",
L368:           //   topic.toStdString().c_str());
L369:         }
L370:       }
L371:     }
L372:   }
L373:   return topics;
L374: }
